function useUnreadBadge(userId: string): number {
  const [count, setCount] = useState<number>(0);

  useEffect(() => {
    const id = setInterval(async () => {
      const next: number = await fetchUnreadCount(userId);
      if (next > count) {
        showToast(`${next - count} new messages`);
      }
      setCount(next);
    }, 15000);
    return () => clearInterval(id);
  }, [userId]);

  return count;
}

type OutboxItem = { id: string; op: 'create' | 'update' | 'delete'; payload: unknown };

export async function flushOutbox(): Promise<void> {
  const items: OutboxItem[] = await outbox.readAll();
  items.forEach(async (item: OutboxItem) => {
    await api.send(item);
    await outbox.remove(item.id);
  });
  await outbox.setLastFlush(Date.now());
}

async function refreshTokens(): Promise<string> {
  const refreshToken: string = await secureStore.get('refresh');
  const res: Response = await fetch(REFRESH_URL, {
    method: 'POST',
    body: JSON.stringify({ refreshToken }),
  });
  const pair: TokenPair = await res.json();
  await secureStore.set('refresh', pair.refreshToken);
  session.accessToken = pair.accessToken;
  return pair.accessToken;
}

export async function authFetch(url: string): Promise<Response> {
  const res: Response = await fetch(url, { headers: authHeader(session.accessToken) });
  if (res.status !== 401) return res;
  const token: string = await refreshTokens();
  return fetch(url, { headers: authHeader(token) });
}
